import { useSearchParams } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { fetchCategories, type Category } from '../lib/api';

export default function CatalogFilterBar() {
  const [searchParams, setSearchParams] = useSearchParams();
  const currentCategory = searchParams.get('category') || 'semua';
  const searchQuery = searchParams.get('q') || '';
  const currentSort = searchParams.get('sort') || 'terbaru';
  const minPrice = searchParams.get('min') || '';
  const maxPrice = searchParams.get('max') || '';

  const [apiCategories, setApiCategories] = useState<Category[]>([]);

  useEffect(() => {
    fetchCategories().then(res => setApiCategories(res.data || [])).catch(() => {});
  }, []);

  const handleCategoryClick = (cat: string) => {
    const newParams = new URLSearchParams(searchParams);
    if (cat === 'Semua') {
      newParams.delete('category');
    } else {
      newParams.set('category', cat.toLowerCase());
    }
    newParams.set('page', '1');
    setSearchParams(newParams);
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newParams = new URLSearchParams(searchParams);
    if (e.target.value) {
      newParams.set('q', e.target.value);
    } else {
      newParams.delete('q');
    }
    newParams.set('page', '1');
    setSearchParams(newParams);
  };

  const handleSortChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newParams = new URLSearchParams(searchParams);
    newParams.set('sort', e.target.value);
    newParams.set('page', '1');
    setSearchParams(newParams);
  };

  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'min' | 'max') => {
    const newParams = new URLSearchParams(searchParams);
    if (e.target.value) {
      newParams.set(type, e.target.value);
    } else {
      newParams.delete(type);
    }
    newParams.set('page', '1');
    setSearchParams(newParams);
  };

  const categories = ['Semua', ...apiCategories.map(c => c.name)];

  return (
    <div className="sticky top-[73px] z-40 bg-surface/90 backdrop-blur-md border-b border-outline-variant/10 py-6 px-4 md:px-8">
      <div className="max-w-7xl mx-auto flex flex-col gap-6">
        {/* Search */}
        <div className="relative w-full">
          <span className="material-symbols-outlined absolute left-4 top-1/2 -translate-y-1/2 text-outline">search</span>
          <input 
            value={searchQuery}
            onChange={handleSearchChange}
            className="w-full bg-surface-container-high border-none rounded-full py-4 pl-12 pr-6 text-on-surface placeholder:text-outline focus:ring-2 focus:ring-primary transition-all" 
            placeholder="Cari kartu Pokemon (e.g. Charizard VMAX, Pikachu Holo...)" 
            type="text"
          />
        </div>
        
        {/* Filters */}
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex flex-wrap gap-2 block no-scrollbar">
            {categories.map((cat) => {
              const isActive = (cat === 'Semua' && (currentCategory === 'semua' || currentCategory === null)) || currentCategory === cat.toLowerCase();
              return (
                <button
                  key={cat}
                  onClick={() => handleCategoryClick(cat)}
                  className={`px-6 py-2 rounded-full font-semibold text-sm transition-all hover:scale-105 ${
                    isActive 
                      ? 'bg-primary text-on-primary'
                      : 'bg-surface-container-high text-on-surface/70 hover:bg-surface-bright hover:text-on-surface'
                  }`}
                >
                  {cat}
                </button>
              );
            })}
          </div>
          
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center bg-surface-container-high rounded-full px-4 py-1">
              <span className="text-xs text-outline mr-2 uppercase tracking-widest font-bold">Price</span>
              <input 
                value={minPrice}
                onChange={(e) => handlePriceChange(e, 'min')}
                className="w-20 bg-transparent border-none text-sm p-1 focus:ring-0 text-on-surface" 
                placeholder="Min" 
                type="number"
              />
              <span className="text-outline mx-1">-</span>
              <input 
                value={maxPrice}
                onChange={(e) => handlePriceChange(e, 'max')}
                className="w-20 bg-transparent border-none text-sm p-1 focus:ring-0 text-on-surface" 
                placeholder="Max" 
                type="number"
              />
            </div>
            
            <select 
              value={currentSort}
              onChange={handleSortChange}
              className="bg-surface-container-high border-none rounded-full py-2 px-6 text-sm font-semibold text-on-surface focus:ring-2 focus:ring-primary"
            >
              <option value="terbaru">Terbaru</option>
              <option value="low-high">Harga Low-High</option>
              <option value="high-low">Harga High-Low</option>
              <option value="populer">Paling Populer</option>
            </select>
          </div>
        </div>
      </div>
    </div>
  );
}
